// Generated bytes are checked in, so ordinary builds need no toolchain.
// This runs `zig build` (build.zig) with the pinned Zig, which compiles
// src/root.zig and, with its clang, minimp3, unchanged, to
// wasm32-freestanding, and writes the module as base64 into src/binary.ts;
// --check verifies the inputs' digest.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  copyFileSync,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const here = fileURLToPath(new URL(".", import.meta.url));
const vendor = fileURLToPath(new URL("../../vendor/minimp3/", import.meta.url));

const ZIG_VERSION = "0.17.0";
/** The release's tarballs, from ziglang.org/download/index.json. */
const ZIG_SHA256: Record<string, string> = {
  "x86_64-linux": "1cbe9df9f27e6b78d14ccbca43b6703a404ef79ef1c463de901d7f088d4e2026",
  "aarch64-linux": "9e8d11661d4ae3bd57702a3832781e23ad151dde5798e16a5ccd503f65234ff8",
};

const include = join(here, "include");
const inputs = [
  fileURLToPath(import.meta.url),
  join(here, "build.zig"),
  join(here, "build.zig.zon"),
  join(here, "src/root.zig"),
  ...readdirSync(include)
    .filter((name) => name.endsWith(".h"))
    .sort()
    .map((name) => join(include, name)),
  join(vendor, "minimp3.h"),
  join(vendor, "LICENSE"),
];
const digest = createHash("sha256").update(ZIG_VERSION);
for (const file of inputs) {
  digest.update(readFileSync(file));
}

const inputDigest = digest.digest("hex");
const target = join(here, "src/binary.ts");
if (process.argv.includes("--check")) {
  if (!readFileSync(target, "utf8").includes(`inputs: ${inputDigest}`)) {
    throw new Error("MP3 decoder inputs changed; run pnpm --filter @swf2es/mp3 build:wasm");
  }
} else {
  const zig = findZig();
  // Fresh caches and prefix each time, so nothing of an earlier build is reused.
  const work = join(tmpdir(), `swf2es-mp3-${process.pid}`);
  mkdirSync(work, { recursive: true });
  try {
    execFileSync(zig, ["build", "--prefix", work], {
      cwd: here,
      stdio: "inherit",
      env: {
        ...process.env,
        ZIG_LOCAL_CACHE_DIR: join(work, "cache"),
        ZIG_GLOBAL_CACHE_DIR: join(work, "global"),
      },
    });
    const bytes = readFileSync(join(work, "bin/mp3.wasm"));
    const module = await WebAssembly.compile(bytes);
    if (WebAssembly.Module.imports(module).length) {
      throw new Error(
        `the MP3 decoder must import nothing: ${JSON.stringify(WebAssembly.Module.imports(module))}`,
      );
    }

    writeFileSync(
      target,
      `// Generated by packages/mp3/build.ts; minimp3 is CC0-1.0.\n// inputs: ${inputDigest}\nexport const binary =\n  "${bytes.toString("base64")}";\n`,
    );
    copyFileSync(join(vendor, "LICENSE"), join(here, "LICENSE.minimp3"));
    console.log(`mp3: ${bytes.length} bytes`);
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

/** Zig on the PATH if it is the pinned version, else the pinned release, downloaded and checked once. */
function findZig(): string {
  try {
    if (execFileSync("zig", ["version"]).toString().trim() === ZIG_VERSION) {
      return "zig";
    }
  } catch {
    // Not on the PATH.
  }

  const platform = `${process.arch === "arm64" ? "aarch64" : "x86_64"}-${process.platform}`;
  const sha256 = ZIG_SHA256[platform];
  if (!sha256 || (process.arch !== "x64" && process.arch !== "arm64")) {
    throw new Error(`put Zig ${ZIG_VERSION} on the PATH to rebuild the MP3 decoder`);
  }

  const name = `zig-${platform}-${ZIG_VERSION}`;
  const cache = join(process.env.XDG_CACHE_HOME ?? join(homedir(), ".cache"), "swf2es");
  const zig = join(cache, name, "zig");
  if (existsSync(zig)) {
    return zig;
  }

  mkdirSync(cache, { recursive: true });
  const archive = join(cache, `${name}.tar.xz`);
  execFileSync("curl", [
    "-fsSL",
    "-o",
    archive,
    `https://ziglang.org/download/${ZIG_VERSION}/${name}.tar.xz`,
  ]);
  const actual = createHash("sha256").update(readFileSync(archive)).digest("hex");
  if (actual !== sha256) {
    rmSync(archive);
    throw new Error(`${name}.tar.xz has SHA-256 ${actual}, not ${sha256}`);
  }

  execFileSync("tar", ["-xJf", archive, "-C", cache]);
  rmSync(archive);
  return zig;
}
